-- v6.99.124 (M4) — aggiunge la variante latina (romanizzazione) su prod
-- per simmetria fresh-seed ≡ prod. Idempotente (NOT EXISTS). Nessun rename
-- prod (il name_original nativo è già corretto). psql -v ON_ERROR_STOP=1.
BEGIN;


-- validazione: ogni entità ha ora la variante latina
DO $$ DECLARE bad int; BEGIN
  SELECT count(*) INTO bad FROM (VALUES (405, 'Mamlakat Fas al-Wattasiyya'),(406, 'Al-Dawla al-Sa''diyya'),(410, 'Saltanat Sinnar'),(411, 'Taqali'),(420, 'Rus'' Kyivska'),(430, 'Sakartvelos samepo'),(434, 'Vtoro Balgarsko Tsarstvo'),(435, 'Srpsko Carstvo'),(436, 'Despotaton tou Moreos'),(438, 'Autokratoria tis Trapezountas'),(440, 'Halytsko-Volynske knyazivstvo'),(658, 'Medri Bahri'),(664, 'Tsarstvo Vidinsko'),(736, 'Dawla al-Mahdiyya')) v(eid, nm) WHERE NOT EXISTS (SELECT 1 FROM name_variants nv WHERE nv.entity_id = v.eid AND nv.name = v.nm);
  IF bad <> 0 THEN RAISE EXCEPTION '% varianti latine mancanti', bad; END IF;
  RAISE NOTICE 'M4 v6.99.124 OK: 14 varianti latine sincronizzate';
END $$;

COMMIT;
